const MODEL_URL="https://teachablemachine.withgoogle.com/models/6uKiaMXZR/";let classifier,video,probDiv,label="대기 중...",conf={Fist:0,Right:0,Left:0,None:0},x=275,y=300,jumping=!1;function preload(){classifier=ml5.imageClassifier(MODEL_URL+"model.json",modelLoaded)}let modelReady=!1;function modelLoaded(){console.log("모델 로드 완료!"),modelReady=!0,video&&video.loadedmetadata&&startClassifying()}function setup(){createCanvas(600,400).parent("game"),video=createCapture(VIDEO),video.size(160,120),video.hide(),video.elt.addEventListener("loadedmetadata",()=>{console.log("웹캠 준비 완료!"),modelReady&&startClassifying()}),probDiv=createDiv(""),probDiv.id("prob"),probDiv.parent("game")}function startClassifying(){console.log("분류 시작..."),classifier.classifyStart(video,gotResults)}function draw(){background(135,206,235),drawFloor(),image(video,width-170,10,160,120),noFill(),stroke(255,87,34),strokeWeight(5),rect(width-170,10,160,120,12),updateProb(),drawChar(),"Left"===label&&(x-=7),"Right"===label&&(x+=7),"Fist"!==label||jumping||jump(),x=constrain(x,0,width-50),select("#gest").html(getName(label))}function updateProb(){const e=["Fist","Right","Left","None"],t={Fist:"주먹",Right:"오른쪽",Left:"왼쪽",None:"없음"},i={Fist:"#ff5722",Right:"#2196f3",Left:"#4caf50",None:"#9e9e9e"};let o=0,l="";e.forEach(e=>{conf[e]>o&&(o=conf[e],l=e)});let a="<b>AI 확신도</b><br>";e.forEach(e=>{let o=150*conf[e];a+=`\n          <div style="margin:5px 0;text-align:left">\n            <div style="color:${e===l?"#d50000":"#333"};font-weight:${e===l?"bold":"normal"}">${t[e]}: ${(100*conf[e]).toFixed(1)}%</div>\n            <div class="bar"><div class="fill" style="width:${o}px;background:${i[e]}"></div></div>\n          </div>`}),probDiv.html(a)}function drawFloor(){fill(139,69,19),rect(0,350,width,50),fill(34,139,34);for(let e=0;e<width;e+=30)rect(e,345,20,10)}function drawChar(){fill(76,175,80),rect(x,y,50,50,12),fill(255),ellipse(x+15,y+18,16),ellipse(x+35,y+18,16),fill(0),ellipse(x+15,y+18,8),ellipse(x+35,y+18,8)}function jump(){jumping=!0,y=200,setTimeout(()=>{y=300,jumping=!1},700)}function gotResults(e){e&&0!==e.length?(console.log("실시간 결과:",e),label=e[0].label,e.forEach(e=>{conf[e.label]=e.confidence})):console.error("결과 없음")}function getName(e){return{Left:"왼쪽",Right:"오른쪽",Fist:"주먹!",None:"없음"}[e]||e}setTimeout(()=>{video&&0!==video.width||alert("웹캠이 안 켜졌어요!\n1. 카메라 권한 허용\n2. 페이지를 새로고침")},5e3);